def observadores_sin_unidades_a_todas(apps, schema_editor):
    """Hasta la 3.9.0 un Observador sin unidades veía toda la empresa. Desde ahora hay
    que elegir unidades o «Todas»: a los que no tenían ninguna se les marca «Todas»
    (con todas las unidades asignadas), para que nadie pierda lo que veía."""
    CustomUser = apps.get_model('usuarios', 'CustomUser')
    UnidadOrganizativa = apps.get_model('strorganizativa', 'UnidadOrganizativa')
    todas = list(UnidadOrganizativa.objects.values_list('pk', flat=True))
